from typing import List

class Solution:
    def mergeKLists(self, lists: List[ListNode]) -> ListNode:
        head = ListNode()
        node = head
        nodes = []
        for l_list in lists:
            while l_list:
                nodes.append(l_list.val)
                l_list = l_list.next
        for val in sorted(nodes):
            node.next = ListNode(val)
            node = node.next
        return head.next

# Input: lists = []
